/**
 * @file cali_wifi_sm.h
 * @brief C twin of the WiFi provisioning and connectivity state machine.
 *
 * The twin of `tools/wifi_sm_ref.py`. Same contract: no strings, no radio and no clock in the SM.
 * Time enters only as WEV_TICK's `arg` (`now_ms`, monotonic ms since boot); WEV_FAILED's `arg` is
 * the reason code; every other event carries no `arg`. A transition that starts a clock leaves
 * `since_ms` = 0 ("unstamped") and the next TICK stamps it. The enum values (WIFI_*, WEV_*, WACT_*)
 * and the timings (NET_*_MS) are pinned in `net_consts.h`, generated by `tools/gen_c_dict.py`:
 * never renumber them by hand.
 *
 * C99, no malloc, no platform deps: it compiles on a host for the parity test (replaying
 * `tests/vectors/wifi_sm.json`) and under ESP-IDF.
 *
 * @verbatim embed:rst:leading-asterisk
 * .. req:: WiFi provisioning — setup hotspot, captive portal, station join with retry, credentials in the kv store
 *    :id: R_FW_WIFI_PROVISION
 *
 *    A satellite with no saved WiFi opens a WPA2 setup hotspot (``calictl-esp-setup``, fixed
 *    passphrase, address ``192.168.4.1``) whose DNS answers every A query with its own address and whose
 *    HTTP server redirects the OS captive-portal probe paths to the web UI (``http://192.168.4.1/``),
 *    which opens on its WiFi-setup screen, so a phone that joins is led to it. Credentials entered there (or with the console's ``wifi set``) are validated (SSID
 *    1-32 bytes, PSK 8-63 bytes — open networks unsupported), stored in the kv store (``wifi_ssid`` /
 *    ``wifi_psk``) and joined as a station; on success mDNS announces ``calictl-esp.local`` and the
 *    hotspot closes ``NET_AP_CLOSE_MS`` later. A failed join of credentials typed in the current setup
 *    flow clears them and returns to the hotspot; credentials that joined before or were loaded from
 *    flash are never wiped by a failure — the station retries on a 1 s to 60 s doubling backoff and
 *    reopens the hotspot alongside after ``NET_SETUP_AFTER_MS`` (5 min) without a join. ``wifi forget``
 *    / ``DELETE /api/wifi`` erase them and reopen the hotspot from any state. ``GET /api/wifi`` lists
 *    networks over the hotspot and while online (a scan at most every ``NET_SCAN_MIN_INTERVAL_MS``,
 *    never during a join or a BLE pairing flow). The state machine is a pure C twin of
 *    ``tools/wifi_sm_ref.py`` (golden-vector parity). A board whose WiFi driver cannot start boots with
 *    WiFi off and the BLE side unaffected.
 * @endverbatim
 */
#ifndef CALI_WIFI_SM_H
#define CALI_WIFI_SM_H
#include <stdint.h>

#include "net_consts.h"

/** @brief One action the WiFi SM asks its driver to run. */
typedef struct {
    uint8_t act;   /**< A WACT_* constant. */
    uint32_t arg;  /**< The reason for WACT_LOG_REASON; 0 otherwise. */
} cali_wifi_action_t;

/** @brief The WiFi SM's state. */
typedef struct {
    uint8_t st;           /**< Current state, a WIFI_* constant. */
    uint8_t ap_up;        /**< 1 once the SM emitted WACT_AP_START, 0 after WACT_AP_STOP. */
    /** 1 = the credentials joined or were loaded from flash (a FAILED retries them).
     *  0 = typed in this setup flow via WEV_CREDS_SET (a FAILED clears them).
     *  WIFI_REPLACING (2) = typed to replace joined credentials via WEV_CREDS_REPLACE (a FAILED
     *  emits WACT_RESTORE_PREV and retries the restored ones). */
    uint8_t joined_once;
    uint32_t retry_ms;    /**< Current backoff interval while (SETUP_AP_)RETRYING. */
    uint64_t since_ms;    /**< When ONLINE or RETRYING began; 0 = not stamped by a TICK yet. */
    uint64_t next_try_ms; /**< Time of the next STA_START while retrying. */
} cali_wifi_state_t;

/**
 * @brief Advance the SM by one event.
 *
 * @param s   Current state, updated in place.
 * @param ev  One of the `WEV_*` constants; unknown events are no-ops.
 * @param arg `now_ms` for `WEV_TICK`, the reason for `WEV_FAILED`; unused otherwise.
 * @param out Receives up to `WIFI_MAX_ACTIONS` actions to run, in order.
 * @return The number of actions written to `out`.
 */
int cali_wifi_step(cali_wifi_state_t *s, uint8_t ev, uint64_t arg,
                   cali_wifi_action_t out[WIFI_MAX_ACTIONS]);

#endif /* CALI_WIFI_SM_H */
